import './App.css';

function App() {
  return (
    <div className="App">
      <header className="App-header">

        <p>Lockr Reservation</p>

      </header>

      <div className="App-body">
        
        <div className="floor-menu">

          <input type="text" className="search-input" placeholder="Search for a locker..." />
  
          <button className="floor-button">Floor 6</button>
          <button className="floor-button">Floor 7</button>
          <button className="floor-button">Floor 8</button>
          <button className="floor-button">Floor 9</button>
          <button className="floor-button">Floor 10</button>

        </div>

      </div>


    </div>
  );
}

export default App;
